package ir.vigoapp.storage;

import java.io.*;
import java.nio.file.Path;
import java.time.Duration;

/**
 * Content-addressed-free opaque object storage. Keys are random hex identifiers
 * generated by the store, never derived from user input.
 *
 * <p>Two implementations share this contract: the local filesystem (development
 * and tests) and S3-compatible object storage (ParsPack). Uploads always stage
 * locally first so {@link FileValidator} can inspect real bytes before anything
 * is promoted to its permanent location.
 */
interface BlobStore {
    /** Value prefix separating public from private objects. Never trust a caller-provided prefix. */
    enum Visibility { PUBLIC, PRIVATE }

    Staged put(InputStream input) throws IOException;

    /** Promotes a validated staged object to permanent storage under the given visibility. */
    void promote(Staged staged, Visibility visibility) throws IOException;

    /** Removes a staged object that never became permanent. */
    void discardStage(Staged staged) throws IOException;

    /**
     * Compensation only: caller must have proven in a fresh transaction that no
     * database row references this key.
     */
    void discardUnreferenced(Staged staged) throws IOException;

    InputStream open(String key, Visibility visibility) throws IOException;

    boolean exists(String key, Visibility visibility) throws IOException;

    long size(String key, Visibility visibility) throws IOException;

    /**
     * Time-limited direct download URL. Private objects must only be presigned
     * after the caller has authorized the request.
     */
    String presignedGet(String key, Visibility visibility, Duration ttl) throws IOException;

    /** Removes a permanent object (soft-deleted metadata never calls this). */
    void delete(String key, Visibility visibility) throws IOException;

    /** Identifier persisted with metadata so reads go back to the writing backend. */
    String backend();

    record Staged(String key, Path path, long size, String sha256) {}
}
